<section class="card">
  <h2>Serviços cadastrados</h2>

  <% if (services.length === 0) { %>
    <p>Nenhum serviço cadastrado.</p>
  <% } else { %>
    <div class="admin-list">
      <% services.forEach(service => { %>
        <form method="post" action="/admin/servicos/<%= service.id %>" class="edit-box">
          <label>
            Nome
            <input type="text" name="name" value="<%= service.name %>" required>
          </label>

          <label>
            Descrição
            <textarea name="description"><%= service.description || '' %></textarea>
          </label>

          <label>
            Preço
            <input type="number" name="price" step="0.01" min="0" value="<%= service.price %>">
          </label>

          <label>
            Duração
            <input type="number" name="duration_minutes" min="1" value="<%= service.duration_minutes %>">
          </label>

          <label class="checkbox">
            <input type="checkbox" name="active" <%= service.active ? 'checked' : '' %>>
            Ativo
          </label>

          <button class="button small" type="submit">Salvar alterações</button>
        </form>
      <% }) %>
    </div>
  <% } %>
</section>

<section class="card">
  <h2>Cadastrar horário disponível</h2>

  <form method="post" action="/admin/horarios" class="wide-form">
    <label>
      Serviço
      <select name="service_id" required>
        <option value="">Selecione</option>
        <% services.filter(s => s.active).forEach(service => { %>
          <option value="<%= service.id %>"><%= service.name %></option>
        <% }) %>
      </select>
    </label>

    <label>
      Data e hora
      <input type="datetime-local" name="start_time" required>
    </label>

    <button class="button" type="submit">Cadastrar horário</button>
  </form>
</section>

<section class="card">
  <h2>Últimos horários cadastrados</h2>

  <% if (slots.length === 0) { %>
    <p>Nenhum horário cadastrado.</p>
  <% } else { %>
    <div class="table-wrap">
      <table>
        <thead>
          <tr>
            <th>Serviço</th>
            <th>Data e hora</th>
            <th>Ação</th>
          </tr>
        </thead>
        <tbody>
          <% slots.forEach(slot => { %>
            <tr>
              <td><%= slot.service_name %></td>
              <td><%= formatDateTime(slot.start_time) %></td>
              <td>
                <form method="post" action="/admin/horarios/<%= slot.id %>/excluir" onsubmit="return confirm('Excluir este horário?')">
                  <button class="danger small-button" type="submit">Excluir</button>
                </form>
              </td>
            </tr>
          <% }) %>
        </tbody>
      </table>
    </div>
  <% } %>
</section>

<section class="card">
  <h2>Todos os agendamentos</h2>

  <% if (appointments.length === 0) { %>
    <p>Nenhum agendamento ainda.</p>
  <% } else { %>
    <div class="table-wrap">
      <table>
        <thead>
          <tr>
            <th>Cliente</th>
            <th>E-mail</th>
            <th>Serviço</th>
            <th>Data e hora</th>
            <th>Status</th>
            <th>Alterar</th>
          </tr>
        </thead>
        <tbody>
          <% appointments.forEach(a => { %>
            <tr>
              <td><%= a.user_name %></td>
              <td><%= a.user_email %></td>
              <td><%= a.service_name %></td>
              <td><%= formatDateTime(a.start_time) %></td>
              <td><span class="status <%= a.status %>"><%= a.status %></span></td>
              <td>
                <form method="post" action="/admin/agendamentos/<%= a.id %>/status" class="status-form">
                  <select name="status">
                    <option value="pending" <%= a.status === 'pending' ? 'selected' : '' %>>Pendente</option>
                    <option value="confirmed" <%= a.status === 'confirmed' ? 'selected' : '' %>>Confirmado</option>
                    <option value="rejected" <%= a.status === 'rejected' ? 'selected' : '' %>>Recusado</option>
                    <option value="cancelled" <%= a.status === 'cancelled' ? 'selected' : '' %>>Cancelado</option>
                  </select>
                  <button class="small-button" type="submit">Salvar</button>
                </form>
              </td>
            </tr>
          <% }) %>
        </tbody>
      </table>
    </div>
  <% } %>
</section>

<%- include('../partials/footer') %>

=== public/css/style.css ===
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: #f4f7fb;
  color: #1f2937;
}

a {
  color: #2563eb;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

.topbar {
  background: #111827;
  color: white;
  padding: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.brand {
  color: white;
  font-size: 22px;
  font-weight: bold;
}

.topbar nav {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

.topbar nav a {
  color: white;
}

.user-name {
  color: #d1d5db;
}

.container {
  width: min(1100px, calc(100% - 24px));
  margin: 24px auto;
}

.hero {
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  color: white;
  border-radius: 18px;
  padding: 40px;
  margin-bottom: 24px;
}

.hero h1 {
  font-size: clamp(30px, 6vw, 52px);
  margin: 0 0 12px;
}

.hero p {
  font-size: 18px;
  max-width: 720px;
}

.card,
.form-card {
  background: white;
  border-radius: 14px;
  padding: 22px;
  margin-bottom: 22px;
  box-shadow: 0 8px 28px rgba(15, 23, 42, 0.08);
}

.form-card {
  max-width: 480px;
  margin-left: auto;
  margin-right: auto;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 16px;
}

.service-card,
.slot-card,
.edit-box {
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 16px;
  background: #fbfdff;
}

.actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 20px;
}

.button,
button {
  background: #2563eb;
  color: white;
  border: 0;
  border-radius: 10px;
  padding: 11px 16px;
  cursor: pointer;
  font-weight: bold;
  display: inline-block;
}

.button:hover,
button:hover {
  background: #1d4ed8;
  text-decoration: none;
}

.button.secondary {
  background: white;
  color: #2563eb;
}

.button.small,
.small-button {
  padding: 8px 12px;
  font-size: 14px;
}

.danger {
  background: #dc2626;
}

.danger:hover {
  background: #b91c1c;
}

.link-button {
  background: transparent;
  padding: 0;
  color: white;
  border: 0;
}

.inline {
  display: inline;
}

form label {
  display: block;
  margin-bottom: 14px;
  font-weight: bold;
}

input,
textarea,
select {
  width: 100%;
  padding: 11px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  margin-top: 6px;
  font: inherit;
  background: white;
}

textarea {
  min-height: 90px;
  resize: vertical;
}

.wide-form {
  max-width: 650px;
}

.checkbox {
  display: flex;
  align-items: center;
  gap: 10px;
}

.checkbox input {
  width: auto;
  margin: 0;
}

.message {
  padding: 14px;
  border-radius: 10px;
  margin-bottom: 18px;
  font-weight: bold;
}

.message.success {
  background: #dcfce7;
  color: #166534;
}

.message.error {
  background: #fee2e2;
  color: #991b1b;
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 680px;
}

th,
td {
  padding: 12px;
  border-bottom: 1px solid #e5e7eb;
  text-align: left;
  vertical-align: middle;
}

th {
  background: #f8fafc;
}

.status {
  display: inline-block;
  border-radius: 999px;
  padding: 5px 10px;
  font-weight: bold;
  font-size: 13px;
}

.status.pending {
  background: #fef3c7;
  color: #92400e;
}

.status.confirmed {
  background: #dcfce7;
  color: #166534;
}

.status.rejected {
  background: #fee2e2;
  color: #991b1b;
}

.status.cancelled {
  background: #e5e7eb;
  color: #374151;
}

.admin-list {
  display: grid;
  gap: 16px;
}

.status-form {
  display: flex;
  gap: 8px;
  align-items: center;
}

.status-form select {
  margin: 0;
  min-width: 140px;
}

.footer {
  text-align: center;
  color: #6b7280;
  padding: 24px;
}

@media (max-width: 650px) {
  .topbar {
    align-items: flex-start;
  }

  .topbar nav {
    width: 100%;
  }

  .hero {
    padding: 26px;
  }

  .card,
  .form-card {
    padding: 16px;
  }

  .status-form {
    flex-direction: column;
    align-items: stretch;
  }
}
